-- The barista rota (PRD §6.3, §10.2 barista_shifts, §10.3 "barista_shifts keys
-- to the session … `session_id`, or `shift_date + slot`", §6.11.1 COL-23, and
-- the §11 access matrix row "Staff & PINs · barista rota": Admin only).
-- Generated by drizzle-kit from db/schema.ts; only this header is hand-written.
--
-- A new table only. No existing row is read, rewritten or dropped, and no
-- money table (orders, order_items, payments) is touched, so it carries no
-- approval marker (src/server/deploy/migration-approval.ts).
--
--   staff_id            the barista on duty (FK staff).
--   shift_date + slot   the plan, made before the session exists. slot is the
--                       session's order of opening that revenue day: 1 = the
--                       first session, 2 = the second (a Sunday evening).
--   session_id          NULL until that session opens; then set by the open.
--                       ON DELETE SET NULL, so the Admin can still delete a
--                       closed session that had a barista on it.
--   notified_at         set once, when the shift-start push was sent.
--   UNIQUE (shift_date, slot, staff_id): one barista is never on the same
--   slot twice. CHECK (slot >= 1).
--
-- The reverse is drizzle/down/0056_barista_rota.down.sql.

CREATE TABLE "barista_shifts" (
	"id" text PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" text DEFAULT 'hofmi' NOT NULL,
	"staff_id" text NOT NULL,
	"shift_date" text NOT NULL,
	"slot" integer NOT NULL,
	"session_id" text,
	"notified_at" timestamp with time zone,
	"created_by_staff_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "barista_shifts_date_slot_staff_unique" UNIQUE("shift_date","slot","staff_id"),
	CONSTRAINT "barista_shifts_slot_positive" CHECK ("barista_shifts"."slot" >= 1)
);
